const operation = $operation || 'addDays';
const inputDate = $date || new Date().toISOString().split('T')[0];
const days = parseInt($days) || 0;
const date2 = $date2;
const format = $format || 'readable';

function parseDate(dateStr) {
    if (!dateStr) return new Date();
    // Handle ISO format
    if (dateStr.includes('T')) return new Date(dateStr);
    // Handle YYYY-MM-DD
    return new Date(dateStr + 'T00:00:00');
}

function formatDate(date, fmt) {
    if (fmt === 'iso') return date.toISOString().split('T')[0];
    if (fmt === 'custom' && $format) return date.toLocaleDateString('en-GB', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' });
    return date.toLocaleDateString('en-GB', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' });
}

switch (operation) {
    case 'addDays':
        const d1 = parseDate(inputDate);
        d1.setDate(d1.getDate() + days);
        return { result: formatDate(d1, format), operation: 'addDays', days: days };

    case 'subtractDays':
        const d2 = parseDate(inputDate);
        d2.setDate(d2.getDate() - days);
        return { result: formatDate(d2, format), operation: 'subtractDays', days: days };

    case 'daysBetween':
        if (!date2) return { error: 'date2 is required for daysBetween operation' };
        const d3 = parseDate(inputDate);
        const d4 = parseDate(date2);
        const diffTime = Math.abs(d4 - d3);
        const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
        return { result: diffDays, operation: 'daysBetween', from: inputDate, to: date2 };

    case 'format':
        const d5 = parseDate(inputDate);
        return { result: formatDate(d5, format), operation: 'format', original: inputDate };

    default:
        return { error: 'Unknown operation. Use: addDays, subtractDays, daysBetween, format' };
}
